public interface RateLimitPolicy {
  boolean allowRequest(String key);
  void reset();
}

public interface PolicyFactory {
  RateLimitPolicy create(String config);
}

public class PolicyRegistry {
  private final ConcurrentHashMap<String, PolicyFactory> registry = new ConcurrentHashMap<>();
  public void register(String name, PolicyFactory factory) { registry.put(name, factory); }
  public RateLimitPolicy create(String name, String config) {
    PolicyFactory f = registry.get(name);
